namespace EquipmentApp.Services;

public sealed class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

namespace EquipmentApp.Services;

public sealed class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a real data-access delay.
        await Task.Delay(500);

        return
        [
            new() { Id = 1, Name = "Forklift #12",       Location = "Warehouse A", LastInspected = new(2026, 6, 15) },
            new() { Id = 2, Name = "Hydraulic Press",     Location = "Shop Floor",  LastInspected = new(2026, 5, 22) },
            new() { Id = 3, Name = "Conveyor Belt C3",    Location = "Warehouse B", LastInspected = new(2026, 7, 1)  },
            new() { Id = 4, Name = "CNC Lathe",           Location = "Machine Bay", LastInspected = new(2026, 4, 10) },
            new() { Id = 5, Name = "Pallet Jack #7",      Location = "Dock 2",      LastInspected = new(2026, 6, 28) },
            new() { Id = 6, Name = "Arc Welder",          Location = "Shop Floor",  LastInspected = new(2026, 3, 18) },
            new() { Id = 7, Name = "Overhead Crane",      Location = "Warehouse A", LastInspected = new(2026, 7, 5)  },
            new() { Id = 8, Name = "Air Compressor",      Location = "Utility Room", LastInspected = new(2026, 5, 30) },
        ];
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using EquipmentApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Equipment Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSub;

    protected override async Task OnInitializedAsync()
    {
        // During the interactive reconnect, try to restore data that was
        // persisted during the SSR prerender — avoids a second service call.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(_items), out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }

        // Register a callback so that during SSR the framework serialises
        // the data into the page HTML for the interactive runtime to pick up.
        _persistSub = ApplicationState.RegisterOnPersisting(() =>
        {
            ApplicationState.PersistAsJson(nameof(_items), _items);
            return Task.CompletedTask;
        });
    }

    public void Dispose() => _persistSub.Dispose();
}

